results={}
for side in ['before','after']:
 build=W/(side+'-all');inventory=C['inventory'](build);owners={}
 for name,row in cases:
  getter='Get_'+row['module'].replace('.','_')+'_prepare'
  paths=[str(Path(key).parent) for key,value in inventory['sections'].items() if ('func '+getter+'(').encode() in value]
  assert len(paths)==1;owners[name]=(paths[0],getter)
 packages=sorted(set(x[0] for x in owners.values()));aliases={n:'p'+str(i) for i,n in enumerate(packages)}
 imports=';'.join(aliases[n]+' "gopurs/output/'+n+'"' for n in packages)
 entries=','.join('{"'+name+'",'+aliases[owners[name][0]]+'.'+owners[name][1]+'(),'+str(row['expected'])+'}' for name,row in cases)
 source='''package main
import("fmt";"testing";r "gopurs/output/gopurs_runtime";'''+imports+''')
func main(){
 cases:=[]struct{name string;prepare r.Value;expected int64}{'''+entries+'''}
 for _,c:=range cases{
  action:=r.Apply(c.prepare,r.Value{})
  run:=func(){v:=r.Apply(action,r.Value{});if v.Type!=r.TypeInt||v.IntVal!=c.expected{panic("unexpected original-action result")}}
  run()
  allocations:=testing.AllocsPerRun(1000,run)
  fmt.Printf("%s %.6f\\n",c.name,allocations)
 }
}
'''
