 command=['go','build','-pgo=off','-o',str(binary),str(main)]
 process=subprocess.run(command,cwd=build/'output',env=env,text=True,capture_output=True)
 (P/(side+'-build.stdout')).write_text(process.stdout);(P/(side+'-build.stderr')).write_text(process.stderr);process.check_returncode()
 output=subprocess.run([str(binary)],cwd=build/'output',env=env,text=True,capture_output=True);output.check_returncode();assert not output.stderr
 (P/(side+'.stdout')).write_text(output.stdout)
 values={n:float(x) for n,x in re.findall(r'^(\S+) ([0-9.]+)$',output.stdout,re.M)}
 assert set(values)==set(owners)
 assert all(value >= 0 for value in values.values())
 assert C['inventory'](build)['provenance']==inventory['provenance']
 sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
 results[side]={'allocations_per_action':values,'expected_result_checks_per_case':1002,'allocs_per_run_iterations':1000,'command':command,'binary_sha256':sha(binary),'source_sha256':sha(main),'original_build':inventory['provenance'],'stdout':output.stdout}
