package main
import("encoding/json";"unsafe";"fmt";"os";r "gopurs/output/gopurs_runtime"
p0 "gopurs/output/purescript/p_cdbf3019a3a300007f3d219dbc66ccf3"
p1 "gopurs/output/purescript/p_root"
)
type Input struct{Case int `json:"case"`;Name string `json:"name"`;Count int64 `json:"count"`;Fields []int64 `json:"fields"`;Layout string `json:"layout"`}
func record(input Input,prepared r.Value)r.Value{
 if input.Layout=="prepared"{return prepared}
 keys:=make([]string,len(input.Fields));values:=make([]r.Value,len(input.Fields));fields:=map[string]r.Value{}
 for i,value:=range input.Fields{keys[i]=string(rune('a'+i));values[i]=r.Int(value);fields[keys[i]]=values[i]}
 if input.Layout=="map"{return r.Record(fields)}
 if input.Layout=="boxed2"{return r.Value{Type:r.TypeRecord2,UnsafePtr:unsafe.Pointer(&r.RecordData2{RecordKeys2:&r.RecordKeys2{K0:keys[0],K1:keys[1]},V0:values[0],V1:values[1]})}}
 if input.Layout=="shape"&&len(keys)==2{return r.RecordShape2(&r.RecordKeys2{K0:keys[0],K1:keys[1]},values[0],values[1])}
 if input.Layout=="reversed"{for i,j:=0,len(keys)-1;i<j;i,j=i+1,j-1{keys[i],keys[j]=keys[j],keys[i];values[i],values[j]=values[j],values[i]}}
 return r.RecordDict(keys,values)
}
func unchanged(value r.Value,input Input){
 for i,expected:=range input.Fields{actual:=r.RecordGet(value,string(rune('a'+i)));if actual.Type!=r.TypeInt||actual.IntVal!=expected{panic("original record field mutated")}}
 if len(r.RecordToMap(value))!=len(input.Fields){panic("record keys changed")}
}
func main(){
 var inputs []Input;f,e:=os.Open(os.Args[1]);if e!=nil{panic(e)};if e=json.NewDecoder(f).Decode(&inputs);e!=nil{panic(e)}
 factories:=map[string]func()r.Value{"RecordSetSmall1000":p0.Get_Test_RecordSetSmall1000_prepare,"RecordSetMedium1000":p0.Get_Test_RecordSetMedium1000_prepare,"RecordSetLarge1000":p1.Get_Test_RecordSetLarge1000_prepare};actions:=map[string]r.Value{};prepared:=map[string]r.Value{}
 for name,factory:=range factories{
   p1.RecordAuditInputs=[]interface{}{nil};p1.RecordAuditCalls=0;p1.RecordAuditPreparing=true
   action:=r.Apply(factory(),r.Value{})
   if p1.RecordAuditCalls!=1{panic("incorrect opaque calls during preparation")}
   p1.RecordAuditPreparing=false
   prepared[name]=r.AnyToValue(p1.RecordAuditPrepared);actions[name]=action
 }
 for _,input:=range inputs{
   action:=actions[input.Name]
   for _,path:=range []string{"Apply","ffi_conversion","forced_fallback"}{
     original:=record(input,prepared[input.Name]);unchanged(original,input)
     alias:=original;mutations:=0
     p1.RecordAuditMutation=func(){mutations++;mutateRecord(alias,string(rune('a'+len(input.Fields)-1)))}
     p1.RecordAuditInputs=[]interface{}{original,r.Int(input.Count)};p1.RecordAuditCalls=0
     var result int64
     if path=="Apply"{value:=r.Apply(action,r.Value{});if value.Type!=r.TypeInt{panic("not an Int")};result=value.IntVal}else{
       selected:=action
       if path=="forced_fallback"{selected=r.Func(func(_ r.Value)r.Value{return r.Apply(action,r.Value{})})}
       result=int64(convertCallback(selected)())
     }
     if p1.RecordAuditCalls!=2{panic("incorrect opaque calls per action")}
     if mutations!=1{panic("alias mutation effect count")}
     changed:=input;changed.Fields=append([]int64{},input.Fields...);last:=len(changed.Fields)-1;changed.Fields[last]=int64(int32(changed.Fields[last]+17))
     unchanged(original,changed);unchanged(alias,changed)
     fmt.Printf("%s %d %s %d\n",input.Name,input.Case,path,result)
   }
 }
}
func convertCallback(arg2 r.Value) func() int {
 go_arg2 := func(__gopurs_action r.Value) func() int {
			if __gopurs_native_action, ok := r.FunctionData[func() int64](__gopurs_action); ok { return func() int { return int(__gopurs_native_action()) } }
			return func() int { return r.Unbox[int](r.Apply(__gopurs_action, r.Value{})) }
		}(arg2)
 return go_arg2
}

func mutateRecord(value r.Value,key string){
 switch value.Type {
 case r.TypeRecord2:
