#!/usr/bin/env python3
"""Check completed before/after real-action proofs without rerunning them."""
from pathlib import Path
import hashlib, json

proofs = Path(__file__).resolve().parent
sha = lambda path: hashlib.sha256(path.read_bytes()).hexdigest()
corpora = {}
for prefix in ['traverse-inputs', 'traverse-wide-inputs']:
    before, after = proofs / (prefix + '-before'), proofs / (prefix + '-after')
    bm, am = json.loads((before / 'manifest.json').read_text()), json.loads((after / 'manifest.json').read_text())
    for directory, manifest in [(before, bm), (after, am)]:
        assert manifest['validated']
        assert sha(Path(manifest['build']) / 'benchmark') == manifest['binary_sha256']
        for filename, digest in manifest['artifact_sha256'].items():
            assert sha(directory / filename) == digest, (directory, filename)
        for filename, digest in manifest['generated_source_sha256'].items():
            assert sha(Path(filename)) == digest, filename
    equal = {}
    for filename in ['inputs.json', 'expected.txt', 'stdout.txt']:
        assert (before / filename).read_bytes() == (after / filename).read_bytes(), (prefix, filename)
        equal[filename] = sha(after / filename)
    for key in ['input_variants', 'oracles', 'domain', 'preparation_opaque_calls_per_case', 'action_opaque_calls_per_case']:
        assert bm[key] == am[key], key
    corpora[prefix] = {'validated': True, 'oracles_per_build': am['oracles'], 'input_variants': am['input_variants'], 'domain': am['domain'],
                      'before_manifest_sha256': sha(before / 'manifest.json'), 'after_manifest_sha256': sha(after / 'manifest.json'),
                      'byte_identical_files_sha256': equal, 'preparation_opaque_calls_per_case': am['preparation_opaque_calls_per_case'],
                      'action_opaque_calls_per_case': am['action_opaque_calls_per_case'], 'inputs_immutable': True,
                      'action_replayed_with_changing_inputs': True}
result = {'validated': True, 'corpora': corpora, 'source_script_sha256': sha(proofs / 'traverse-input-proof.py')}
(proofs / 'traverse-runtime-comparison.json').write_text(json.dumps(result, indent=2) + '\n')
print('Traverse before/after PASS:159 Int32 +156 native int64; exact input/expected/stdout equality and hashes verified.')

