import fs from 'node:fs';
const wide = process.argv[3] === 'wide';
for(const input of JSON.parse(fs.readFileSync(process.argv[2],'utf8'))){
 const result = wide
  ? input.values.reduce((a,b,i)=>BigInt.asIntN(32,a+BigInt(1+i%2)*BigInt.asIntN(32,BigInt(b)+1n)),0n)
  : input.values.reduce((a,b,i)=>(a+(((1+i%2)*((Number(b)+1)|0))|0))|0,0);
 for(const path of ['Apply','ffi_conversion','forced_fallback'])console.log(`TraverseMaybe1000 ${input.case} ${path} ${result}`);
}

