package main
import("flag";"fmt";"testing";r "gopurs/output/gopurs_runtime";root "gopurs/output/purescript/p_root";_ "gopurs/output/purescript/init_all")
var sink int64
func verify(){
 checks:=0
 counts:=[]int64{0,1,2,7,1000,2147483647,4294967297,4294967298,4294967303,-4294967295,-4294967294}
 vals:=[]int64{0,1,-1,2147483647,2147483648,-2147483648,-2147483649,9223372036854775807,-9223372036854775808}
 for _,n:=range counts{for _,v:=range vals{
  m:=recordMedium{P_a:v,P_b:v+1,P_c:v-1,P_d:4,P_e:5,P_f:6,P_g:7,P_h:v}
  l:=recordLarge{P_a:v,P_b:2,P_c:3,P_d:4,P_e:5,P_f:6,P_g:7,P_h:8,P_i:9,P_j:10,P_k:11,P_l:12,P_m:13,P_n:14,P_o:15,P_p:v}
  if hotMedium(n,m)!=root.Call_Test_RecordSetMedium1000_updateMedium(n,m){panic("medium mismatch")};checks++
  if hotLarge(n,l)!=root.Call_Test_RecordSetLarge1000_updateLarge(n,l){panic("large mismatch")};checks++
 }};fmt.Println(checks,"native wrapper/original checks passed")
}
func main(){testing.Init();flag.Parse();verify();cases:=[]struct{name string;get func()r.Value;want int64}{{"medium/linear",Get_probe_LinearMedium,1072},{"medium/hot",Get_probe_HotMedium,1072},{"large/linear",Get_probe_LinearLarge,1272},{"large/hot",Get_probe_HotLarge,1272}};for _,c:=range cases{action:=r.Apply(c.get(),r.Value{});if got:=r.Apply(action,r.Value{}).IntVal;got!=c.want{panic(fmt.Sprint(c.name,got,c.want))};b:=testing.Benchmark(func(b *testing.B){for i:=0;i<b.N;i++{sink=r.Apply(action,r.Value{}).IntVal}});fmt.Printf("%s %.3f ns/op %d B/op %d allocs/op\n",c.name,float64(b.T.Nanoseconds())/float64(b.N),b.AllocedBytesPerOp(),b.AllocsPerOp())}}

